with lines as (select id, effective_from, currency, tier_value from price_tiers lateral view explode(tier_limits) t as tier_value) select date_trunc('quarter', effective_from) as quarter_start, sum(case when currency = 'EUR' then tier_value else 0 end) as eur_tier_value, round(avg(tier_value), 2) as avg_tier_value, count(*) filter (where currency = 'USD') as usd_rows, count(*) filter (where currency = 'EUR') as eur_rows, count_if(currency = 'THB') as thb_events, count_if(currency = 'EUR') as eur_events from lines group by 1 having eur_rows < 1000 order by usd_rows
